instruction: Debug the following C++ code that is supposed to print the elements of a 2D array but instead crashes without any clear error message. Also, enhance the code by adding functions to perform column and row major traversals of the 2D array.

response: The C++ code likely crashes due to accessing out-of-bounds array indices or using uninitialized pointers. Here's a corrected and enhanced version:

```cpp
#include <iostream>
#include <vector>

// Function to print 2D array in row-major order
void printRowMajor(const std::vector<std::vector<int>>& matrix) {
    std::cout << "Row-major traversal:\n";
    for (const auto& row : matrix) {
        for (int val : row) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    }
}

// Function to print 2D array in column-major order
void printColumnMajor(const std::vector<std::vector<int>>& matrix) {
    std::cout << "Column-major traversal:\n";
    if (matrix.empty() || matrix[0].empty()) return;
    int rows = matrix.size();
    int cols = matrix[0].size();
    for (int col = 0; col < cols; ++col) {
        for (int row = 0; row < rows; ++row) {
            std::cout << matrix[row][col] << " ";
        }
        std::cout << std::endl;
    }
}

// Function to safely print the 2D array
void printMatrix(const std::vector<std::vector<int>>& matrix) {
    if (matrix.empty()) {
        std::cout << "Empty matrix.\n";
        return;
    }
    std::cout << "Matrix:\n";
    for (const auto& row : matrix) {
        for (int val : row) {
            std::cout << val << " ";
        }
        std::cout << std::endl;
    }
}

int main() {
    // Example 2D array
    std::vector<std::vector<int>> matrix = {
        {1, 2, 3},
        {4, 5, 6},
        {7, 8, 9}
    };

    // Safe printing
    printMatrix(matrix);

    // Traversal functions
    printRowMajor(matrix);
    printColumnMajor(matrix);

    return 0;
}
```

Key fixes:
- Used `std::vector` instead of raw arrays to avoid buffer overflows.
- Added bounds checking.
- Implemented proper traversal functions.
- Used range-based for loops for safety and readability.

